    total = n * (n + 1) // 2
    target = (total - 1) // 2  # 0-indexed position of the median

    def count_subarrays_with_at_most(k):
        left = 0
        freq = {}
        distinct = 0
        count = 0
        for right in range(n):
            val = nums[right]
            freq[val] = freq.get(val, 0) + 1
            if freq[val] == 1:
                distinct += 1
            while distinct > k:
                left_val = nums[left]
                freq[left_val] -= 1
                if freq[left_val] == 0:
                    distinct -= 1
                left += 1
            count += right - left + 1
        return count

    low, high = 1, n
    while low < high:
        mid = (low + high) // 2
        if count_subarrays_with_at_most(mid) > target:
