        return

    it = iter(data)
    N = next(it)
    H = next(it)
    W = next(it)

    tiles = []
    tile_area = []
    for _ in range(N):
        a = next(it)
        b = next(it)
        tiles.append((a, b))
        tile_area.append(a * b)

    target_cells = H * W
    full_mask = (1 << target_cells) - 1
    all_tiles_mask = (1 << N) - 1
    total_area = sum(tile_area)

    area_sum = [0] * (1 << N)
    for mask in range(1, 1 << N):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        area_sum[mask] = area_sum[mask ^ lsb] + tile_area[idx]

    # The used tiles must have total area exactly target_cells.
    possible_initial_area = False
    for mask in range(1 << N):
        if area_sum[mask] == target_cells:
            possible_initial_area = True
            break
    if not possible_initial_area:
        print("No")
        return

    def rect_mask(r, c, h, w):
        row = (1 << w) - 1
        mask = 0
        for rr in range(h):
            mask |= row << ((r + rr) * W + c)
        return mask

    placements = []
    for a, b in tiles:
        masks = set()
        for h, w in ((a, b), (b, a)):
            if h <= H and w <= W:
                for r in range(H - h + 1):
                    for c in range(W - w + 1):
                        masks.add(rect_mask(r, c, h, w))
        placements.append(tuple(masks))

    # cover_by_cell[i][cell] = placements of tile i covering that cell
    cover_by_cell = []
    for i in range(N):
        by_cell = [[] for _ in range(target_cells)]
        for mask in placements[i]:
            m = mask
            while m:
                lsb = m & -m
                cell = lsb.bit_length() - 1
                by_cell[cell].append(mask)
                m ^= lsb
        cover_by_cell.append([tuple(lst) for lst in by_cell])

    @lru_cache(maxsize=None)
    def dfs(fill, used):
        if fill == full_mask:
            return True

        covered = fill.bit_count()
        remaining = target_cells - covered
        if remaining <= 0:
            return False

        used_area = area_sum[used]
        if total_area - used_area < remaining:
            return False

        # Remaining area must be formable by a subset of unused tiles.
        unused = all_tiles_mask ^ used
        sub = unused
        can_make_area = False
        while True:
            if area_sum[sub] == remaining:
                can_make_area = True
                break
            if sub == 0:
                break
            sub = (sub - 1) & unused

        if not can_make_area:
            return False

        # Choose an empty cell with the fewest placement options.
        best_cell = -1
        best_count = 10**9

        for cell in range(target_cells):
            cell_bit = 1 << cell
            if fill & cell_bit:
                continue

            cnt = 0
            for i in range(N):
                if used & (1 << i):
                    continue
                if tile_area[i] > remaining:
                    continue

                for mask in cover_by_cell[i][cell]:
                    if not (mask & fill):
                        cnt += 1
                        if cnt >= best_count:
                            break

                if cnt >= best_count:
                    break

            if cnt == 0:
                return False

            if cnt < best_count:
                best_count = cnt
                best_cell = cell

        if best_cell == -1:
            return False

        candidates = []
        for i in range(N):
            if used & (1 << i):
                continue
            if tile_area[i] > remaining:
                continue

            for mask in cover_by_cell[i][best_cell]:
                if not (mask & fill):
                    candidates.append((i, mask))

        candidates.sort(key=lambda x: tile_area[x[0]], reverse=True)

        for i, mask in candidates:
            if dfs(fill | mask, used | (1 << i)):
                return True

        return False

    print("Yes" if dfs(0, 0) else "No")


