def maximumJumps(nums, target):
    n = len(nums)
    # dp[i] represents the maximum number of jumps to reach index i
    dp = [-1] * n
    dp[0] = 0  # We start at index 0, so 0 jumps needed

    for i in range(n):
        if dp[i] == -1:
            continue  # Cannot reach index i

        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[j] == -1:
                    dp[j] = dp[i] + 1
                else:
                    dp[j] = max(dp[j], dp[i] + 1)

    return dp[n - 1]
